from pathlib import Path
p=Path('/workspace/sites/circulation-atlas/dist')
def doc(id,title,author,date,year,kind,outlet,url,quote,selects,argument,context,**kw):return dict(id=id,title=title,author=author,date=date,year=year,kind=kind,outlet=outlet,url=url,quote=quote,selects=selects,argument=argument,context=context,**kw)
D=[
doc('means','Ideology wars','Marianne Means','24 April 1996',1996,'Press','South Florida Sun Sentinel · p. 19','https://www.newspapers.com/image/238744873/','When bad people make bad things happen, our national psyche drives us to search for a deep meaning.','Political affiliations, the Oklahoma City comparison, and demands for an ideological explanation.','Means challenges attempts to assign responsibility to liberalism or environmentalism. Yet her account also explains violence through an individualized picture of frustration and madness.','A syndicated column reproduced in the newspaper. Its display quotation and accompanying cartoon organize the reading before the argument begins.',image='assets/ideology-wars.jpg',carrier='Newspaper scan',locator='Attached bundle N01 · PDF page 1',verification='Scan inspected',relation='Compare with Mickelson’s report: a columnist’s intervention and a reporter’s use of expert testimony.',pair='taylor'),
doc('taylor','Thin link between radicals, bomber','Sandy Mickelson','11 April 1996',1996,'Press','Oshkosh Northwestern · p. 11','https://www.newspapers.com/image/247845486/','Thin link between radicals, bomber','An expert’s distinction between expressed affinity and the positions of environmental groups.','The report brings Bron Taylor’s knowledge of radical environmentalism to bear on the association being made around Kaczynski. Similarity is itself an object of dispute.','The headline and subheading foreground a challenge to comparison. Read the clipping as a journalistic construction of expertise, as well as a source about the dispute.',image='assets/thin-link.jpg',carrier='Newspaper scan',locator='Attached bundle N01 · PDF page 16',verification='Scan inspected',relation='Paired analytically with Means; no direct reply between these articles is asserted.',pair='means'),
doc('crash','Crash the Parties!','UNAPACK NYC','1996',1996,'Campaign','NOT BORED! · no. 26','https://notbored.org/crash.html','casting an absurd protest vote','The widely published author, the electoral non-choice, and the absurdity of a candidate who would not serve.','The NYC statement turns the Unabomber into an electoral intervention. The intended object is a protest vote; its significance is made through juxtaposition with the available candidates.','This is the campaign’s own announcement. Its rhetoric should be read alongside reporting on the campaign and disagreements between its participants.',image='assets/crash.gif',carrier='Campaign graphic + HTML',locator='Third substantive paragraph of the press release',verification='Publisher text checked',imageCaption='Graphic reproduced with the press release on NOT BORED!; not a facsimile of the complete release.',relation='Compare with Brown’s account of the relationship between NYC and Boston.',pair='brown'),
doc('brown','One campaign, different projects','Bill Brown, interviewed by Joey Manley','1996',1996,'Interview','NOT BORED!','https://notbored.org/manley.html','There is no real ideological unity between New York and Boston.','Decentralized organizing, local invention, and the practical circulation of flyers and posters.','Brown describes participation without central approval. His account prevents the campaign from being represented as one stable ideology or one collective intention.','An organizer explaining the campaign in an interview. The statement is evidence of his account of internal differences, not a complete record of every participant’s position.',carrier='Interview transcription',locator='Answer describing establishment of the NYC office',verification='Publisher text checked',relation='Read against the NYC release and the Boston organizers’ broadcast interview.',pair='korda'),
doc('korda','Distinct from the Unabomber’s positions','Chris Korda, interviewed with Lydia Eccles','9 September 1996',1996,'Broadcast','Democracy Now!','https://www.thetedkarchive.com/library/nomination-for-unabomber-for-president',"our positions, which of course are distinct from the Unabomber's positions.",'The public persona and anti-industrial critique as resources for the campaign’s own politics.','Korda explicitly distinguishes the organizers’ positions from those of their nominal candidate. The campaign’s use of his notoriety does not establish full ideological agreement.','This excerpt is from a later transcript mirror of the broadcast. The original programme and audio are linked in the source record; the audio has not been checked against the transcription.',carrier='Broadcast transcript mirror',locator='Korda’s paragraph introducing the campaign website',verification='Transcript checked · audio unchecked',relation='Compare with Brown on NYC/Boston differences. Both complicate the idea of one campaign position.',pair='brown'),
doc('fulano','The Unabomber and the Future of Industrial Society','T. Fulano (David Watson)','Fall 1996',1996,'Magazine','Fifth Estate · no. 348','https://www.fifthestate.org/archive/348-fall-1996/the-unabomber-and-the-future-of-industrial-society/','We need neither condemn nor condone him','The manifesto, the media persona, industrial violence, and the limits of individual attacks.','Fulano’s critique moves across the text and the social world in which it becomes meaningful. The refusal of a simple condemn/condone choice is part of an argument, not an endorsement stripped of its surrounding criticism.','The essay became an object of disagreement in the magazine’s letters pages. Read its concluding position beside Eccles’s response.',carrier='Publisher transcription',locator='Concluding section, paragraph beginning “We need neither…”',verification='Publisher text checked',relation='Eccles responds to this essay in Fifth Estate #349; Fulano then replies.',pair='eccles'),
doc('eccles','Put the system on trial?','Lydia Eccles','Summer 1997',1997,'Correspondence','Fifth Estate · no. 349','https://www.fifthestate.org/archive/349-summer-1997/letters-to-the-fifth-estate/','Can we put the technological-industrial system on trial?','The trial as a public occasion and the possibility of redirecting its political attention.','Eccles contests the earlier essay and asks what might be made of the trial. Her intervention shifts the question toward the opportunities created by a mediated event.','A published letter signed with the Unapack campaign affiliation. This is public correspondence, not the private June 1996 letter referenced in the dissertation’s archival notes.',carrier='Published letter · transcription',locator='End of Eccles’s letter, before signature and Fulano reply',verification='Publisher text checked',relation='A documented response to Fulano’s Fall 1996 essay. The same page carries his rebuttal.',pair='fulano'),
doc('faun','Fixed Ideas and Letter Bombs','Formerly Feral Faun / Wolfi Landstreicher','Spring 1997',1997,'Magazine','Green Anarchist · nos. 45–46','https://www.thetedkarchive.com/library/wolfi-landstreicher-fixed-ideas-and-letter-bombs','FC’s statement has many faults','The manifesto’s explanatory concepts, especially psychology and the “power process.”','The article takes the manifesto seriously enough to criticize its analytical foundations. Publication in Green Anarchist does not mean that its contributors speak with one voice.','The archive supplies page images and an unfinished transcription. The scan is the primary visual object; the online OCR contains errors.',image='assets/fixed-ideas.jpg',carrier='Magazine scan + transcription',locator='Opening discussion; displayed page image from the archive',verification='Scan available · OCR incomplete',relation='Compare with Moore’s focus on ideological motivation rather than treating “anarchist reception” as uniform.',pair='moore'),
doc('moore','Beyond the Fragments','John Moore','Spring 1998',1998,'Magazine','Green Anarchist · no. 51','https://theanarchistlibrary.org/library/john-moore-beyond-the-fragments-a-reaction-to-industrial-society-and-its-future','a question of ideological motivation','The manifesto’s ideological commitments and competing responses to the bomber.','Moore distinguishes his criticism of the text from condemnation of the bombings. His opening challenges the polarity between rejection and romanticization.','A later transcription identifies the original publication as Green Anarchist #51. The original issue layout is not reproduced here.',carrier='Magazine transcription',locator='Introduction · paragraph beginning “Rather, however…”',verification='Transcription and issue metadata checked',relation='An analytical comparison with Feral Faun; this pairing does not assert a direct exchange.',pair='faun'),
doc('ace','Not part of the same movement','Autonomous Centre of Edinburgh','31 July 1998',1998,'Statement','ACE · supported by Scottish Anarchist Network','https://libcom.org/article/autonomous-centre-edinburgh-statement-green-anarchist-3171998','Our objection is not on the basis of pacifism','Green Anarchist’s political positions, revolutionary participation, and the distinction between solidarity and agreement.','ACE rejects GA’s politics while opposing state repression of the publication. Supporting freedom to publish and belonging to the same movement are explicitly separated.','A statement of meeting decisions, later rehosted on libcom in 2016. The statement’s description of GA is an attributed criticism; it must not stand in for all GA contributions.',carrier='Statement · later transcription',locator='Second substantive paragraph',verification='Statement text checked',relation='Compare with an individual GA contribution to see why the publication cannot be reduced to either a critic’s description or a single author.',pair='moore'),
doc('tedits','An inheritance refused','Ted Kaczynski','2 September 2012',2012,'Correspondence','Letter excerpt to “Anonymous with Caution”','https://www.thetedkarchive.com/library/ted-kaczynski-on-individualists-tending-toward-savagery-its','ITS’ understanding of revolution is at a kindergarten level.','ITS’s interpretation of revolution and the relation between technological progress and the whole system.','Kaczynski disputes the understanding attributed to ITS. An author’s rejection is part of the textual afterlife, not proof that a reader had no relationship to the work.','An excerpt of correspondence, reproduced online with a source pointing to Último Reducto’s blog. It is not an image of the original letter.',carrier='Letter excerpt · transcription',locator='Second paragraph of reproduced excerpt',verification='Text and date checked · original letter unavailable',relation='Place beside Último Reducto’s critique; both contest attribution and interpretation.',pair='ur'),
doc('ur','Who gets to interpret the text?','Último Reducto','Hosted version dated 2015',2015,'Critique','Comments on the communiqués from ITS','https://theanarchistlibrary.org/library/ultimo-reducto-comments-on-the-communiques-from-individualists-tending-toward-the-wild','ITS have misinterpreted some aspects of Kaczynski’s ideas','Statements ITS attributes to Kaczynski and the textual grounds for disputing them.','Último Reducto treats interpretation as something to adjudicate through passages and concepts. The assertion of misreading is the critic’s position, not a neutral fact supplied by the exhibit.','The hosted item contains material attributed to Último Reducto and Kaczynski. The displayed excerpt belongs to UR’s numbered point 4. The host’s 2015 date does not establish the composition date of every component.',carrier='Critique · translated transcription',locator='Último Reducto · numbered point 4',verification='Relevant section checked',relation='Pair with the 2012 letter without treating the host date as proof of the exchange’s sequence.',pair='tedits')]
source_titles={'brown':'Interview with the Unabomber for President Political Action Committee NYC','korda':'Nomination for Unabomber for President','eccles':'Letters to the Fifth Estate [Lydia Eccles letter]','ace':'Autonomous Centre of Edinburgh statement on Green Anarchist','tedits':'Ted Kaczynski on Individualists Tending to the Wild (ITS)','ur':'Comments on the communiques from Individualists Tending toward the Wild','moore':'Beyond the Fragments: A Reaction to Industrial Society and Its Future'}
