G=[dict(id='press',number='01',title='Guilt by association',period='APRIL 1996',subtitle='The press makes an ideological biography.',intro='Once a suspect has a name, the search for explanation reaches into his education, politics, and presumed affinities. These two newspaper objects show that those connections were disputed within coverage itself.',question='When does a resemblance become an explanation?',docs=['means','taylor']),dict(id='campaign',number='02',title='Making a candidate',period='1996',subtitle='Unapack assembles a protest from a persona.',intro='An author, a suspect, a candidate who would not serve. Unapack’s participants selected these figures differently. The differences between Boston and New York matter as much as the campaign’s shared name.',question='What can be borrowed without being endorsed?',docs=['crash','brown','korda']),dict(id='magazines',number='03',title='Against a single reading',period='1996–1998',subtitle='Anarchist magazines become sites of disagreement.',intro='Agreement that industrial society demands criticism does not settle what to make of the manifesto, its author, or his violence. Essays and published letters turn those questions into disputes between readers.',question='What does a publication’s disagreement make visible?',docs=['fulano','eccles','faun','moore']),dict(id='boundaries',number='04',title='The limits of solidarity',period='1998',subtitle='A movement argues over its own boundaries.',intro='Opposing repression need not imply political affiliation. The ACE statement makes that separation explicit. Read its claims alongside the diversity of arguments published within Green Anarchist.',question='Who can speak for a movement?',docs=['ace','moore','faun']),dict(id='inheritance',number='05',title='An inheritance refused',period='2012 / 2015',subtitle='ITS and the authority to interpret.',intro='A text’s circulation does not end in faithful adoption. Kaczynski and Último Reducto contest interpretations associated with ITS. Their objections reveal a struggle over what the texts authorize.',question='Does the author control what readers make of a text?',docs=['tedits','ur'])]
rows=[]
for b in sorted(json.load(open('/workspace/scratch/e27e3582e197/corpus/newspaper-extracted-text.json')),key=lambda x:x['name']):
 a=re.split(r'<PARSED TEXT FOR PAGE: (\d+) / \d+>','\n'.join(b['content']))
 for i in range(1,len(a),2):
  s=a[i+1];m=re.search(r'https?://(?:www\.)?newspapers\.com/image/\d+/?',s);h=re.sub(r'\s+',' ',s[:m.start()] if m else s[:180]).strip();h=re.sub(r'^Newspapers\s*','',h);h=re.sub(r'by\s+.{0,15}?ancestry[’\x27]?','',h,flags=re.I).strip()
  rows.append(dict(id=f'N{b["name"][:2]}-{int(a[i]):03}',title=h,url=m.group() if m else '',attachment='https://chatgpt.com/library?file_id='+b['library_file_id']+'&account_id=personal',page=int(a[i])))
(p/'data.js').write_text('const DOCUMENTS = '+json.dumps(D,ensure_ascii=False)+';\nconst DOSSIERS = '+json.dumps(G,ensure_ascii=False)+';\nconst NEWS_INDEX = '+json.dumps(rows,ensure_ascii=False)+';')
(p/'corpus.md').write_text(Path('/workspace/scratch/e27e3582e197/corpus/Some_Assembly_Required_Corpus.md').read_text())
